export class KeyPair {
    free(): void;
    [Symbol.dispose](): void;
    constructor();
    toJs(): any;
}

export class Nanopub {
    free(): void;
    [Symbol.dispose](): void;
    check(): Nanopub;
    static fetch(uri: string): Promise<any>;
    info(): any;
    constructor(rdf: any);
    publish(profile: NpProfile | undefined, server_url?: string | null): Promise<any>;
    static publish_intro(profile: NpProfile, server_url: string): Promise<any>;
    rdf(): string;
    sign(profile: NpProfile): Nanopub;
    toString(): string;
}

/**
 * Nanopub profile in JavaScript
 */
export class NpProfile {
    free(): void;
    [Symbol.dispose](): void;
    __getClassname(): string;
    constructor(private_key: string, orcid_id?: string | null, name?: string | null, introduction_nanopub_uri?: string | null);
    toJs(): any;
    toString(): string;
}

/**
 * Return a random server or the main nanopub server. Default to random server
 */
export function getNpServer(random?: boolean | null): string;

export function startup(): void;

